import heapq

class Solution:
    def mostBooked(self, n: int, meetings: list[list[int]]) -> int:
        meetings.sort()
        free_rooms = list(range(n))
        heapq.heapify(free_rooms)
        busy_rooms = []
        count = [0] * n

        for start, end in meetings:
            duration = end - start
            while busy_rooms and busy_rooms[0][0] <= start:
                _, room = heapq.heappop(busy_rooms)
                heapq.heappush(free_rooms, room)

            if free_rooms:
                room = heapq.heappop(free_rooms)
                heapq.heappush(busy_rooms, (end, room))
            else:
                earliest_end, room = heapq.heappop(busy_rooms)
                heapq.heappush(busy_rooms, (earliest_end + duration, room))
            count[room] += 1

        max_meetings = max(count)
        return count.index(max_meetings)

class Solution {
public:
    int mostBooked(int n, std::vector<std::vector<int>>& meetings) {
        std::sort(meetings.begin(), meetings.end());
        std::priority_queue<int, std::vector<int>, std::greater<int>> free_rooms;
        for (int i = 0; i < n; i++) free_rooms.push(i);

        using P = std::pair<long long, int>;
        std::priority_queue<P, std::vector<P>, std::greater<P>> busy_rooms;
        std::vector<int> count(n, 0);

        for (const auto& m : meetings) {
            long long start = m[0], end = m[1];
            long long duration = end - start;

            while (!busy_rooms.empty() && busy_rooms.top().first <= start) {
                free_rooms.push(busy_rooms.top().second);
                busy_rooms.pop();
            }

            if (!free_rooms.empty()) {
                int room = free_rooms.top();
                free_rooms.pop();
                busy_rooms.push({end, room});
                count[room]++;
            } else {
                auto [earliest_end, room] = busy_rooms.top();
                busy_rooms.pop();
                busy_rooms.push({earliest_end + duration, room});
                count[room]++;
            }
        }

        int max_idx = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[max_idx]) max_idx = i;
        }
        return max_idx;
    }
};

class Solution {
    public int mostBooked(int n, int[][] meetings) {
        java.util.Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.PriorityQueue<Integer> freeRooms = new java.util.PriorityQueue<>();
        for (int i = 0; i < n; i++) freeRooms.offer(i);

        java.util.PriorityQueue<long[]> busyRooms = new java.util.PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            return Long.compare(a[1], b[1]);
        });
        int[] count = new int[n];

        for (int[] m : meetings) {
            long start = m[0], end = m[1];
            long duration = end - start;

            while (!busyRooms.isEmpty() && busyRooms.peek()[0] <= start) {
                freeRooms.offer((int) busyRooms.poll()[1]);
            }

            if (!freeRooms.isEmpty()) {
                int room = freeRooms.poll();
                busyRooms.offer(new long[]{end, room});
                count[room]++;
            } else {
                long[] top = busyRooms.poll();
                long earliestEnd = top[0];
                int room = (int) top[1];
                busyRooms.offer(new long[]{earliestEnd + duration, room});
                count[room]++;
            }
        }

        int maxIdx = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[maxIdx]) maxIdx = i;
        }
        return maxIdx;
    }
}

var mostBooked = function(n, meetings) {
    meetings.sort((a, b) => a[0] - b[0]);
    const freeRooms = Array.from({ length: n }, (_, i) => i);
    const busyRooms = [];
    const count = new Array(n).fill(0);

    for (const [start, end] of meetings) {
        const duration = end - start;
        while (busyRooms.length > 0 && busyRooms[0].endTime <= start) {
            busyRooms.sort((a, b) => a.endTime - b.endTime || a.room - b.room);
            if (busyRooms[0].endTime > start) break;
            const released = busyRooms.shift();
            freeRooms.push(released.room);
            freeRooms.sort((a, b) => a - b);
        }

        if (freeRooms.length > 0) {
            const room = freeRooms.shift();
            busyRooms.push({ endTime: end, room });
            busyRooms.sort((a, b) => a.endTime - b.endTime || a.room - b.room);
            count[room]++;
        } else {
            busyRooms.sort((a, b) => a.endTime - b.endTime || a.room - b.room);
            const earliest = busyRooms.shift();
            busyRooms.push({ endTime: earliest.endTime + duration, room: earliest.room });
            busyRooms.sort((a, b) => a.endTime - b.endTime || a.room - b.room);
            count[earliest.room]++;
        }
    }

    let maxIdx = 0;
    for (let i = 1; i < n; i++) {
        if (count[i] > count[maxIdx]) maxIdx = i;
    }
    return maxIdx;
};
